export const GENERATED_STYLE_BANNER = "/* Generated by build-styles.mjs. Edit canonical CSS sources instead. */";

const normalize = (value) => String(value).replace(/\r\n?/g, "\n");

function importPattern() {
  return /^[ \t]*@import\s+url\(\s*["']?\/([^"')]+)["']?\s*\)\s*;[ \t]*(?:\n|$)/gm;
}

export async function createStyleBundle(readSource, entry = "styles.css") {
  if (typeof readSource !== "function") throw new TypeError("createStyleBundle requires a stylesheet reader.");

  const flatten = async (name, stack = []) => {
    const normalizedName = String(name || "").replace(/^\/+/, "");
    if (!normalizedName) throw new Error("Stylesheet dependency name must not be empty.");
    if (stack.includes(normalizedName)) {
      throw new Error(`Circular stylesheet import: ${[...stack, normalizedName].join(" -> ")}`);
    }

    const source = normalize(await readSource(normalizedName));
    const pattern = importPattern();
    let cursor = 0;
    let flattened = `/* Source: ${normalizedName} */\n`;
    let match;
    while ((match = pattern.exec(source)) !== null) {
      flattened += source.slice(cursor, match.index);
      flattened += await flatten(match[1], [...stack, normalizedName]);
      cursor = match.index + match[0].length;
    }
    flattened += source.slice(cursor);
    return `${flattened.trimEnd()}\n`;
  };

  const bundle = `${GENERATED_STYLE_BANNER}\n${await flatten(entry)}`;
  if (/@import\s/i.test(bundle)) {
    throw new Error("Generated production stylesheet must not contain @import rules.");
  }
  return bundle;
}
